{
  "story": "Water moves endlessly through Earth. It evaporates from oceans, condenses into clouds, and precipitates back down.",
  "aha": {
    "stateId": "precip",
    "observation": "Precipitation returns condensed atmospheric water back to the surface, completing the planetary loop."
  },
  "layout": {
    "preset": "stepper-vertical",
    "width": 640
  },
  "parts": [
    {
      "id": "rail",
      "kind": "step-rail",
      "bind": {
        "active": "inputs.stepIndex",
        "items": "variant.states"
      }
    },
    {
      "id": "picture",
      "kind": "fixed-picture",
      "bind": {
        "active": "state.active",
        "regions": "variant.regions",
        "completedBefore": "state.id"
      }
    },
    {
      "id": "callout",
      "kind": "active-callout",
      "bind": {
        "reason": "state.why",
        "target": "state.calloutRegion",
        "text": "state.sentence"
      }
    },
    {
      "id": "readout",
      "kind": "value-readout",
      "bind": {
        "values": "state.readouts"
      }
    },
    {
      "id": "prog",
      "kind": "progress",
      "bind": {
        "completedBefore": "inputs.stepIndex"
      }
    }
  ],
  "controls": [
    {
      "id": "stepIndex",
      "kind": "index",
      "label": "Cycle Step",
      "options": [
        "Evaporation",
        "Condensation",
        "Precipitation",
        "Collection"
      ]
    },
    {
      "id": "resetBtn",
      "kind": "reset",
      "label": "Reset Cycle",
      "options": []
    }
  ],
  "data": {
    "variants": [
      {
        "label": "Water Cycle Process",
        "regions": [
          {
            "id": "ocean",
            "label": "Ocean Source",
            "kind": "reservoir",
            "values": ["96.5% water"]
          },
          {
            "id": "sun",
            "label": "Solar Energy",
            "kind": "energy",
            "values": ["Heat flux"]
          },
          {
            "id": "clouds",
            "label": "Atmosphere",
            "kind": "vapor",
            "values": ["Condensate"]
          },
          {
            "id": "land",
            "label": "Surface Runoff",
            "kind": "ground",
            "values": ["Aquifer recharge"]
          }
        ],
        "states": [
          {
            "id": "evap",
            "label": "Evaporation",
            "short": "Evap",
            "sentence": "Solar heat converts liquid ocean water into invisible water vapor.",
            "why": "Energy input drives phase change from liquid to gas.",
            "active": ["ocean", "sun"],
            "calloutRegion": "ocean",
            "readouts": [
              {
                "id": "r1",
                "label": "Phase",
                "value": "Liquid to Gas"
              }
            ]
          },
          {
            "id": "cond",
            "label": "Condensation",
            "short": "Cond",
            "sentence": "Warm vapor rises, cools, and clusters around particles to form clouds.",
            "why": "Lower atmospheric temperatures trigger droplet formation.",
            "active": ["clouds"],
            "calloutRegion": "clouds",
            "readouts": [
              {
                "id": "r2",
                "label": "Phase",
                "value": "Gas to Liquid"
              }
            ]
          },
          {
            "id": "precip",
            "label": "Precipitation",
            "short": "Precip",
            "sentence": "Heavy droplets overcome updrafts and fall as rain, snow, or sleet.",
            "why": "Droplet mass exceeds cloud support capacity.",
            "active": ["clouds", "land"],
            "calloutRegion": "land",
            "readouts": [
              {
                "id": "r3",
                "label": "Phase",
                "value": "Downward Flux"
              }
            ]
          },
          {
            "id": "collect",
            "label": "Collection",
            "short": "Collect",
            "sentence": "Water flows across terrain into rivers and returns to oceans.",
            "why": "Gravity pulls surface water toward base level elevations.",
            "active": ["land", "ocean"],
            "calloutRegion": "ocean",
            "readouts": [
              {
                "id": "r4",
                "label": "Phase",
                "value": "Surface Runoff"
              }
            ]
          }
        ]
      }
    ]
  }
}
